<?php
if (!defined('ABSPATH')) exit;
final class SEO_Manager_Migration {public static function init():void{add_action('admin_post_seom_import_plugin',[__CLASS__,'import']);add_action('admin_post_seom_export',[__CLASS__,'export']);}public static function detect():array{$found=[];if(defined('WPSEO_VERSION'))$found[]='Yoast SEO';if(defined('RANK_MATH_VERSION'))$found[]='Rank Math';if(defined('AIOSEO_VERSION'))$found[]='All in One SEO';return $found;}public static function import():void{if(!current_user_can('manage_options')||!check_admin_referer('seom_import_plugin'))wp_die('Unauthorized');$source=sanitize_key($_POST['source']??'');if(function_exists('set_time_limit'))@set_time_limit(0);$posts=get_posts(['post_type'=>seom_post_types(),'post_status'=>'any','posts_per_page'=>-1,'fields'=>'ids']);foreach($posts as $id){$title=$desc=$kw='';if($source==='yoast'){ $title=(string)get_post_meta($id,'_yoast_wpseo_title',true);$desc=(string)get_post_meta($id,'_yoast_wpseo_metadesc',true);$kw=(string)get_post_meta($id,'_yoast_wpseo_focuskw',true);}elseif($source==='rankmath'){ $title=(string)get_post_meta($id,'rank_math_title',true);$desc=(string)get_post_meta($id,'rank_math_description',true);$kw=(string)get_post_meta($id,'rank_math_focus_keyword',true);}elseif($source==='aioseo'){ $title=(string)get_post_meta($id,'_aioseo_title',true);$desc=(string)get_post_meta($id,'_aioseo_description',true);}if($title!==''&&!seom_meta($id,'title'))update_post_meta($id,'_seom_title',sanitize_text_field($title));if($desc!==''&&!seom_meta($id,'description'))update_post_meta($id,'_seom_description',sanitize_textarea_field($desc));if($kw!==''&&!seom_meta($id,'keyword'))update_post_meta($id,'_seom_keyword',sanitize_text_field($kw));}wp_safe_redirect(add_query_arg(['page'=>'seo-manager-tools-group','subtab'=>'status','migrated'=>1],admin_url('admin.php')));exit;}
 public static function export():void{if(!current_user_can('manage_options')||!check_admin_referer('seom_export'))wp_die('Unauthorized');$rows=[];foreach(get_posts(['post_type'=>seom_post_types(),'post_status'=>'any','posts_per_page'=>-1,'fields'=>'ids']) as $id)$rows[]=['id'=>$id,'post_type'=>get_post_type($id),'url'=>get_permalink($id),'title'=>seom_meta($id,'title'),'description'=>seom_meta($id,'description'),'keyword'=>seom_meta($id,'keyword'),'canonical'=>seom_meta($id,'canonical')];nocache_headers();header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename=seo-manager-export-'.gmdate('Y-m-d').'.json');echo wp_json_encode($rows);exit;}}
